const parseOrder = (payload: string) => {
  const obj = JSON.parse(payload);
  if (!obj.items) throw new Error("missing items");
  return {
    id: String(obj.id || ""),
    items: Array.isArray(obj.items) ? obj.items : [obj.items],
    note: obj.note || ""
  };
};

// Version A: Accept lenient inputs, normalize, emit strict outbound message
function handleMessageA(raw: any) {
  const msg = parseIncoming(raw);
  const normalized = {
    id: String(msg.id || ""),
    type: msg.type || "unknown",
    payload: Array.isArray(msg.payload) ? msg.payload : [msg.payload]
  };
  sendOutbound(normalized);
}

// Version B: Strictly validate and forward raw payload as received
function handleMessageB(raw: any) {
  if (!isValid(raw)) throw new Error("invalid message");
  sendOutbound(raw);
}
